require 'net/smtp'
require 'socket'
require 'logger'

module ContainerOrchestrator
  class NotificationService
    HEADER_SANITIZE_PATTERN = /[\r\n]/

    def initialize(smtp_host: 'localhost', smtp_port: 25)
      @smtp_host = smtp_host
      @smtp_port = smtp_port
      @logger = Logger.new(STDOUT)
      @shutdown_requested = false
      @pending_notifications = []
      @mutex = Mutex.new
    end

    def sanitize_header_value(value)
      value.to_s.gsub(HEADER_SANITIZE_PATTERN, ' ').strip
    end

    def encode_recipient(name, email)
      clean_name = sanitize_header_value(name)
      clean_email = sanitize_header_value(email)
      "#{clean_name} <#{clean_email}>"
    end

    def build_notification_headers(container_id:, event:, recipients:, custom_headers: {})
      headers = {
        'From' => 'orchestrator@internal.cluster.local',
        'Subject' => sanitize_header_value("Container #{container_id}: #{event}"),
        'X-Container-ID' => sanitize_header_value(container_id),
        'X-Event-Type' => sanitize_header_value(event),
        'MIME-Version' => '1.0',
        'Content-Type' => 'text/plain; charset=UTF-8'
      }

      custom_headers.each do |key, value|
        header_key = sanitize_header_value(key.to_s)
        headers[header_key] = sanitize_header_value(value)
      end

      headers['To'] = recipients.map { |r| encode_recipient(r[:name], r[:email]) }.join(', ')
      headers
    end
  end

  class GracefulShutdownHandler
    def initialize(notification_service)
      @service = notification_service
      @drain_timeout = 30
      @logger = Logger.new(STDOUT)
    end

    def format_shutdown_report(containers, operator_contact)
      report_lines = containers.map do |c|
        sanitized_id = c[:id].to_s.gsub(/[\r\n]/, ' ')
        sanitized_status = c[:status].to_s.gsub(/[\r\n]/, ' ')
        sanitized_node = c[:node].to_s.gsub(/[\r\n]/, ' ')
        "Container #{sanitized_id} - Status: #{sanitized_status} - Node: #{sanitized_node}"
      end
      report_lines.join("\n")
    end

    def send_shutdown_notification(operator_name:, operator_email:, containers:, reason:)
      recipients = [{ name: operator_name, email: operator_email }]

      sanitized_reason = reason.to_s.gsub(/[\r\n]/, ' ')
      report = format_shutdown_report(containers, operator_email)

      headers = @service.build_notification_headers(
        container_id: 'SYSTEM',
        event: "Graceful Shutdown: #{sanitized_reason}",
        recipients: recipients,
        custom_headers: { 'X-Shutdown-Reason' => sanitized_reason }
      )

      body = compose_message(headers, report, sanitized_reason)
      deliver(body, operator_email)
    end

    private

    def compose_message(headers, report, reason)
      header_block = headers.map { |k, v| "#{k}: #{v}" }.join("\r\n")
      sanitized_report = report.to_s.gsub(/\r\n/, "\n").gsub(/\r/, "\n")
      "#{header_block}\r\n\r\n#{sanitized_report}\r\nShutdown reason: #{reason}"
    end

    def deliver(message, recipient_email)
      Net::SMTP.start(@service.instance_variable_get(:@smtp_host),
                      @service.instance_variable_get(:@smtp_port)) do |smtp|
        smtp.send_message(message, 'orchestrator@internal.cluster.local', recipient_email)
      end
    rescue => e
      @logger.error("Failed to deliver shutdown notification: #{e.message}")
    end
  end

  class Orchestrator
    def initialize
      @notification_service = NotificationService.new
      @shutdown_handler = GracefulShutdownHandler.new(@notification_service)
      @containers = []
      @logger = Logger.new(STDOUT)
      setup_signal_handlers
    end

    def setup_signal_handlers
      Signal.trap('TERM') { initiate_shutdown('SIGTERM received') }
      Signal.trap('INT') { initiate_shutdown('SIGINT received') }
    end

    def register_container(id:, image:, node:, status: 'running')
      @containers << { id: id, image: image, node: node, status: status }
    end

    def initiate_shutdown(reason)
      @logger.info("Initiating graceful shutdown: #{reason}")
      drain_containers
      notify_operator(reason)
    end

    def notify_operator(reason)
      operator = fetch_operator_config
      @shutdown_handler.send_shutdown_notification(
        operator_name: operator[:name],
        operator_email: operator[:email],
        containers: @containers,
        reason: reason
      )
    end

    private

    def drain_containers
      @containers.each { |c| c[:status] = 'draining' }
    end

    def fetch_operator_config
      # In production, this reads from etcd/consul
      # The operator name comes from cluster configuration
      {
        name: ENV.fetch('OPERATOR_NAME', 'Cluster Admin'),
        email: ENV.fetch('OPERATOR_EMAIL', 'admin@cluster.local')
      }
    end
  end
end
